ee:message.ee:set-payload:
%dw 2.0
var sender_id = Mule::p('sage.login.senderId')
var sender_password = Mule::p('sage.login.senderPass')
var timestamp = uuid()
var user_id = Mule::p('sage.login.userId')
var company_id = Mule::p('sage.login.companyId')
var user_password = Mule::p('sage.login.userPass')
var guid = uuid()

output application/xml  
---

  request: {
    control: {
      senderid: sender_id,
      password: sender_password,
      controlid: timestamp,
      uniqueid: false,
      dtdversion: "3.0",
      includewhitespace: false
    },
    operation: {
      authentication: {
        sessionid: vars.sessionId
      },
      content: {
        function @("controlid": guid): {
          create: {
            CONTRACT: {
              CONTRACTID: vars.inputPayload.Contract_ID__c,
              CUSTOMERID: vars.inputPayload.Customer__c,
              NAME: vars.inputPayload.Name__c,
              STATE: vars.inputPayload.Status__c,
              //CONTRACTTYPE: vars.inputPayload.Contract_Type__c,
              BILLTOCONTACTNAME: "B_" ++ vars.inputPayload.Customer__c,
              DESCRIPTION: "",
              SHIPTOCONTACTNAME: "S_" ++ vars.inputPayload.Customer__c,
              BEGINDATE: vars.inputPayload.Start_Date__c,
              ENDDATE: vars.inputPayload.End_Date__c,
              BILLINGFREQUENCY: "Monthly",
              TERMNAME: vars.inputPayload.Payment_Terms__c,
              APPLICATION: "Contracts",
              ADDITIONALCONTACTNAME: null,
              EVERGREENMACRO: if (upper(vars.inputPayload.Renewal_Term_Type__c) == "EVERGREEN") vars.inputPayload.Renewal_Template__c else "",
              PRCLIST: null,
              MEAPRCLIST: null,
              ADVBILLBY: null,
              "ADDITIONALCONTACTNAME": null,
              "ADVBILLBYTYPE": null,
              "RENEWALADVBILLBY": null,
              "RENEWALADVBILLBYTYPE": null,
              "LOCATIONID": vars.inputPayload.Entity__c,
              "DEPARTMENTID": null,
              "PROJECTID": null,
              "VENDORID": null,
              "EMPLOYEEID": null,
              "CLASSID": null,
              "CURRENCY": vars.inputPayload.CurrencyIsoCode,
              "TERMTYPE" : vars.inputPayload.Contract_Type__c,
              "RENEWAL": vars.inputPayload.Renew__c,
              "RENEWALMACRO": if (upper(vars.inputPayload.Renewal_Term_Type__c) == "TERMED") vars.inputPayload.Renewal_Template__c else "",
              "RENEWTERMLENGTH": vars.inputPayload.Renewal_Term_Length_in_Months__c,
              "RENEWTERMPERIOD": "Months",
              "BASECURR": vars.inputPayload.CurrencyIsoCode,
              "MEGAENTITYID": vars.inputPayload.Entity__c,
              EXCHRATETYPE: 
                if (vars.inputPayload.Entity__c == "E-110")
                  "AUD Bank Rate"
                else
                  "Intacct Daily Rate"
            }
          }
        }
      }
    }
  }
